import { clause, type Category } from "../types";

/**
 * Bilit.Events Promoter & Event Services Agreement — GLOBAL version (Bilit's own text, one clause per section).
 * GENERATED by scripts/promoter-agreement/gen-global.py from agreement.md — edit the markdown, not this file.
 * Rendered in this order with the document's own numbering (agreement type `ordered`). No per-event Schedules.
 */
const c = (key: string, title: string, body: string) => clause(key, title as Category, "core", title.charAt(0) + title.slice(1).toLowerCase(), `Section: ${title}`, body);

export const PROMOTER_GLOBAL = [
  c("pg.01_platform", "PLATFORM", "This Promoter & Event Services Agreement (\"Agreement\") is entered into between:\nBilit.Events / {{organisation_name}}\nCompany Registration No.: {{bilit_company_number}}\nCustomer No.: {{bilit_customer_number}}\nZone: {{bilit_zone}}\nRegistered Office: {{organisation_address}}\nEmail: {{support_email}}\nWebsite: https://bilit.events\nHereinafter referred to as \"Bilit\", \"Platform\", \"we\", \"us\" or \"our\"."),
  c("pg.02_promoter_organiser", "PROMOTER / ORGANISER", "Legal Name: {{organiser_company}}\nTrading Name: {{organiser_trading_name}}\nCompany/Registration No.: {{organiser_registration_number}}\nRegistered Address: {{organiser_address}}\nCountry of Registration: {{organiser_country}}\nEmail: {{organiser_email}}\nTelephone: {{organiser_phone}}\nAuthorised Representative: {{organiser_name}}, {{organiser_title}}\nHereinafter referred to as \"Promoter\", \"Organiser\", \"you\" or \"your\".\nBilit and the Promoter are individually a \"Party\" and together the \"Parties\".\nThis Agreement is a global agreement: it applies to every Event of the Promoter for which an Event Schedule is agreed, without the need to sign this Agreement again for each Event."),
  c("pg.03_definitions_and_interpretation", "DEFINITIONS AND INTERPRETATION", "3.1 In this Agreement the following words have the following meanings:\n\"Advance Payment\" means any advance, prepayment, float or other amount paid by Bilit to or for the Promoter before the Net Settlement Amount for the relevant Event has become due.\n\"Affiliate\" means any person that controls, is controlled by or is under common control with the Promoter, and any person through which the Promoter organises or promotes an Event.\n\"Applicable Law\" means all laws, regulations, licence conditions, card scheme rules and payment processor requirements that apply to a Party, an Event or the sale of Tickets.\n\"Booking Fee\" means the booking, service or platform fee charged by Bilit in respect of a Ticket or an order, as set out in the Event Schedule or, where none is agreed, Bilit's standard fee under clause 5.\n\"Business Day\" means a day other than a Saturday, Sunday or public holiday in England.\n\"Chargeback\" means any reversal, dispute, retrieval request or claim raised by a cardholder, card issuer, bank or payment processor in respect of a payment for Tickets.\n\"Customer\" means any person who buys, books, is issued or holds a Ticket.\n\"Event\" means any event, performance, concert, party, festival or experience promoted, organised or presented by or for the Promoter or any of its Affiliates for which Tickets are listed, sold or issued through the Platform.\n\"Event Schedule\" means the commercial and operational terms for an Event agreed under clause 5.\n\"Funds Held\" means all amounts collected by Bilit from Customers in respect of the Promoter's Events that have not yet been paid to the Promoter.\n\"Gross Ticket Revenue\" means all amounts paid by Customers for Tickets to an Event, including Booking Fees, before any deduction.\n\"Net Settlement Amount\" has the meaning given in clause 11.3.\n\"Platform\" means Bilit's websites (including https://bilit.events), applications and ticketing, payment, scanning and event-management systems.\n\"Promoter Debt\" means any amount payable by the Promoter to Bilit under this Agreement or any Event Schedule, including unrecovered Advance Payments, refunds, refunded Booking Fees, chargebacks, fees, costs and interest.\n\"Ticket\" means any right of admission to an Event, or to any product or experience connected with it, sold or issued through the Platform in any format.\n3.2 In this Agreement: headings do not affect interpretation; \"including\" and similar words do not limit the words before them; the singular includes the plural and vice versa; \"writing\" includes email; a reference to a law includes it as amended or re-enacted; and an obligation not to do something includes an obligation not to permit it to be done.\n3.3 No rule of construction shall apply to the disadvantage of a Party on the basis that the Party prepared this Agreement or any part of it.\n3.4 The Promoter is responsible for the acts and omissions of its Affiliates, officers, employees, contractors, performers, venues and suppliers as if they were its own. Where an Affiliate organises an Event or lists Tickets through the Promoter's account, the Promoter and that Affiliate are jointly and severally liable for all obligations relating to that Event."),
  c("pg.04_purpose_of_the_agreement", "PURPOSE OF THE AGREEMENT", "4.1 The Promoter appoints Bilit to provide event ticketing, payment processing, ticket distribution, customer support and related technology services in connection with the Event(s) identified in the applicable Event Schedule.\n4.2 Bilit operates a technology platform through which tickets and/or admissions to events may be marketed, sold, issued, managed, scanned and administered.\n4.3 Unless expressly agreed otherwise in writing, Bilit acts as a ticketing and technology service provider and does not assume responsibility for the organisation, production, safety, legality, staffing, performers, venue, licensing or delivery of the Event.\n4.4 The Promoter remains solely responsible for the successful delivery of the Event and all obligations owed to ticket purchasers, attendees, performers, venues, suppliers, authorities and third parties."),
  c("pg.05_event_schedule", "EVENT SCHEDULE", "Each Event shall be subject to an Event Schedule containing the commercial and operational details of that Event.\nThe Event Schedule shall include, where applicable:\n• Event name;\n• Event date;\n• Event time;\n• Venue;\n• Venue address;\n• Capacity;\n• Ticket categories;\n• Ticket prices;\n• Currency;\n• Booking fee;\n• Payment processing fee;\n• Promoter settlement percentage or amount;\n• Bilit commission;\n• Deposit/prepayment;\n• Settlement date;\n• Refund policy;\n• Cancellation policy;\n• Promoter bank details;\n• Event-specific terms.\nThe Event Schedule forms an integral part of this Agreement.\nIf there is a conflict between this Agreement and an Event Schedule, the Event Schedule shall prevail only in respect of the specific commercial terms expressly stated in it.\nAn Event Schedule is agreed, and binds the Promoter, when it is (a) signed or accepted electronically by both Parties; (b) confirmed by the Promoter by email; or (c) where Bilit has notified the Promoter of the commercial terms for an Event, the Promoter lists, publishes or permits the sale of Tickets for that Event on the Platform.\nIf Tickets for an Event are sold through the Platform without an agreed Event Schedule, Bilit's standard commercial terms notified to the Promoter or published on the Platform at the time of sale shall apply to that Event.\nThis Agreement applies to every Event without the need to sign it again. Each Event Schedule incorporates the terms of this Agreement."),
  c("pg.06_appointment_of_bilit", "APPOINTMENT OF BILIT", "6.1 The Promoter appoints Bilit as its ticketing and event technology provider for the Event.\n6.2 Bilit may provide:\na. online ticket sales;\nb. payment processing;\nc. ticket issuance;\nd. QR/barcode ticket generation;\ne. ticket scanning;\nf. seating management;\ng. customer communications;\nh. event administration;\ni. sales reporting;\nj. settlement reporting;\nk. refunds processing;\nl. fraud and payment-risk controls;\nm. customer support;\nn. promotional and marketing tools where separately agreed.\n6.3 Bilit may use third-party payment processors, banks, card schemes, fraud-prevention providers, hosting providers and other service providers."),
  c("pg.07_promoter_representations_and_warranties", "PROMOTER REPRESENTATIONS AND WARRANTIES", "The Promoter represents and warrants that:\n7.1 it has full legal capacity and authority to enter into this Agreement;\n7.2 all information supplied to Bilit is true, complete and accurate;\n7.3 it has all necessary rights, licences, permissions and authorisations required to organise and conduct the Event;\n7.4 it has authority to sell tickets to the Event;\n7.5 it has obtained all necessary agreements with the venue;\n7.6 it has obtained all necessary performer, artist, agent, promoter and supplier agreements;\n7.7 the Event does not infringe any intellectual property, contractual, privacy or other third-party rights;\n7.8 the Event complies with all applicable laws and regulations in the country where it takes place;\n7.9 it will comply with all applicable tax obligations;\n7.10 it will comply with applicable health and safety requirements;\n7.11 it will maintain all required insurance;\n7.12 it will not use Bilit for unlawful, fraudulent or misleading activities;\n7.13 the individual accepting this Agreement on its behalf is duly authorised to do so and the Promoter has obtained all corporate approvals required to enter into and perform it;\n7.14 it is not insolvent, is able to pay its debts as they fall due, and no insolvency, winding-up or similar proceedings are pending or threatened against it.\nEach warranty is given on the date of this Agreement and is repeated on the date of each Event Schedule and on each day on which Tickets for an Event are on sale. The Promoter shall notify Bilit in writing without delay of any change of control, change of directors, insolvency event or any circumstance that makes any warranty untrue."),
  c("pg.08_event_licences_and_permits", "EVENT LICENCES AND PERMITS", "8.1 The Promoter is solely responsible for obtaining and maintaining all licences, permits, consents and approvals required for the Event.\n8.2 This includes, where applicable:\n• venue licences;\n• entertainment licences;\n• music licences;\n• alcohol licences;\n• security approvals;\n• local authority permissions;\n• fire and safety approvals;\n• capacity approvals;\n• immigration/work permissions;\n• artist permits;\n• visa requirements;\n• insurance;\n• copyright licences;\n• public performance licences;\n• special event licences.\n8.3 Bilit shall not be responsible for any failure by the Promoter to obtain such licences or approvals."),
  c("pg.09_ticket_prices_and_fees", "TICKET PRICES AND FEES", "9.1 Ticket prices shall be agreed in the Event Schedule.\n9.2 Bilit may charge a booking/service fee as specified in the Event Schedule.\n9.3 The booking fee may be:\n• included in the advertised ticket price;\n• added at checkout;\n• charged as a percentage;\n• charged as a fixed amount; or\n• calculated according to the commercial terms agreed for the Event.\n9.4 Unless otherwise agreed in writing, Bilit's booking/service fee is consideration for services already provided and shall not automatically be refundable merely because an Event is subsequently cancelled.\n9.5 Payment processing charges, currency conversion charges, bank charges, chargeback fees and other third-party costs may be deducted from amounts otherwise payable to the Promoter.\n9.6 Where any Booking Fee is refunded to a Customer for any reason (including where required by Applicable Law, card scheme rules or a payment processor, or because an Event is cancelled, postponed or materially changed), the Promoter shall reimburse Bilit for the full amount refunded. That amount is a Promoter Debt and may be recovered under clause 10.5, save where the refund was caused solely by Bilit's own breach of this Agreement.\n9.7 Bilit's Booking Fee and other fees are earned when the relevant Ticket is sold."),
  c("pg.10_payment_processing", "PAYMENT PROCESSING", "10.1 Payments may be processed through Bilit's payment providers.\n10.2 Bilit does not guarantee that every attempted payment will succeed.\n10.3 Bilit may refuse, delay, reverse, hold or review a transaction where reasonably necessary for:\n• fraud prevention;\n• chargeback protection;\n• compliance;\n• sanctions screening;\n• payment processor requirements;\n• suspicious activity;\n• technical problems;\n• legal requirements.\n10.4 The Promoter authorises Bilit to deduct applicable fees, refunds, chargebacks, penalties, costs and amounts owed under this Agreement from amounts otherwise payable to the Promoter.\n10.5 Bilit may at any time, without notice, set off any Promoter Debt against any amount owed by Bilit to the Promoter or to any of its Affiliates, under this Agreement, any Event Schedule or otherwise, in respect of any Event (past, current or future), whether or not either amount is liquidated or due.\n10.6 The Promoter shall pay all Promoter Debts in full, in cleared funds, within 7 calendar days of written demand, without any set-off, counterclaim, deduction or withholding except as required by law.\n10.7 Overdue Promoter Debts bear interest from the due date until payment at 8% per year above the Bank of England base rate, accruing daily and compounding monthly. The Promoter shall also pay all costs incurred by Bilit in recovering any Promoter Debt or enforcing this Agreement, including legal, arbitration and collection costs, on a full indemnity basis."),
  c("pg.11_promoter_settlement", "PROMOTER SETTLEMENT", "11.1 Subject to this Agreement, Bilit shall calculate the Promoter's settlement amount following the Event.\n11.2 The settlement calculation may include:\nGross Ticket Revenue\nless:\n• Bilit booking/service fees;\n• payment processing fees;\n• refunds;\n• chargebacks;\n• chargeback fees;\n• taxes where applicable;\n• discounts funded by the Promoter;\n• promotional credits funded by the Promoter;\n• other agreed deductions;\n• amounts owed by the Promoter to Bilit.\n11.3 The resulting amount shall be the Net Settlement Amount.\n11.4 Bilit may delay settlement where there is a reasonable risk of:\n• refunds;\n• chargebacks;\n• customer claims;\n• Event cancellation;\n• fraud;\n• regulatory issues;\n• unpaid obligations;\n• disputes.\n11.5 Bilit may retain a reasonable reserve from the settlement for a period reasonably necessary to protect against such liabilities.\n11.6 Unless otherwise stated in the Event Schedule, Bilit shall pay the Net Settlement Amount within 14 Business Days after the Event, subject to clauses 11.4, 11.5, 10.5 and 60.\n11.7 Bilit shall make a settlement statement available to the Promoter. A settlement statement is final and binding unless the Promoter disputes it in writing, with full particulars of each disputed item, within 14 calendar days of it being made available. Any undisputed amount remains payable.\n11.8 Bilit's records, including Platform transaction data and payment processor reports, are conclusive evidence of Ticket sales, refunds, chargebacks, fees and amounts collected, save for manifest error.\n11.9 Bilit receives payments from Customers as the Promoter's limited payment collection agent for the sole purpose of receiving those payments, so that payment to Bilit discharges the Customer's obligation to pay for the Ticket. Funds Held are not held on trust, may be held together with Bilit's own funds, and do not earn interest for the Promoter. The Promoter's only entitlement is a contractual right to be paid the Net Settlement Amount when it becomes due under this Agreement."),
  c("pg.12_advance_payments_prepayments", "ADVANCE PAYMENTS / PREPAYMENTS", "12.1 If Bilit agrees to make an advance or prepayment to the Promoter before the Event, such payment shall constitute an Advance Payment.\n12.2 The Advance Payment shall be recoverable by Bilit from future ticket revenue or directly from the Promoter.\n12.3 If the Event is cancelled, postponed, materially changed or fails to take place, the Promoter shall immediately repay the Advance Payment to Bilit, subject to any amount properly retained by Bilit under this Agreement.\n12.4 Bilit may offset any Advance Payment against:\n• future settlements;\n• ticket revenue;\n• refunds;\n• chargebacks;\n• other amounts payable to the Promoter.\n12.5 If there is insufficient ticket revenue to recover the Advance Payment, the Promoter shall pay the outstanding balance to Bilit within 7 calendar days of written demand.\n12.6 Any Advance Payment is made at Bilit's sole discretion and does not oblige Bilit to make any further advance. Each Advance Payment is a Promoter Debt from the date it is paid and becomes immediately repayable on demand upon any Promoter Default, termination of this Agreement, or the cancellation, postponement or material change of the relevant Event.\n12.7 Bilit may require a personal guarantee, deposit or other security under clause 60 before making any Advance Payment."),
  c("pg.13_event_cancellation_by_promoter", "EVENT CANCELLATION BY PROMOTER", "13.1 The Promoter must not cancel an Event without notifying Bilit immediately.\n13.2 If the Promoter cancels an Event, the Promoter shall be responsible for all refunds and associated costs arising from the cancellation, subject to applicable law and the terms communicated to customers.\n13.3 The Promoter shall reimburse Bilit for amounts reasonably incurred in connection with the cancellation, including where applicable:\n• ticket refunds;\n• payment processing losses;\n• chargeback fees;\n• customer support costs;\n• bank fees;\n• currency conversion losses;\n• reasonable administrative costs;\n• amounts already paid to third parties;\n• promotional costs agreed to be funded by the Promoter.\n13.4 Bilit may deduct such amounts from any funds held on behalf of the Promoter.\n13.5 If the funds held are insufficient, the Promoter shall pay the outstanding balance within 7 calendar days.\n13.6 An Event is treated as cancelled by the Promoter for the purposes of this Agreement if it does not take place on the advertised date, at the advertised venue and with the advertised headline performer(s), unless Bilit has agreed in writing to a postponement, change of venue or change of performer. This applies whatever the cause, including a Force Majeure event, except where the cancellation results solely from Bilit's breach of this Agreement."),
  c("pg.14_event_cancellation_by_bilit", "EVENT CANCELLATION BY BILIT", "Bilit may suspend ticket sales, remove an Event, terminate the Event listing or take other protective action if:\na. the Promoter breaches this Agreement;\nb. the Promoter provides false or misleading information;\nc. Bilit reasonably suspects fraud;\nd. required licences or permissions are unavailable;\ne. payment processing is suspended;\nf. the Event creates material legal, financial, reputational or operational risk;\ng. the Promoter fails to pay amounts due;\nh. the venue becomes unavailable;\ni. the Promoter fails to provide required documentation;\nj. a payment processor, bank or regulatory authority requires such action;\nk. continuing the Event would reasonably expose Bilit to liability."),
  c("pg.15_event_postponement", "EVENT POSTPONEMENT", "15.1 The Promoter shall not postpone an Event without first notifying Bilit.\n15.2 Bilit may determine, acting reasonably and subject to applicable law, whether existing tickets remain valid for the new date.\n15.3 Where refunds are legally required, the Promoter shall bear the financial responsibility for such refunds and associated costs.\n15.4 Bilit may suspend settlement until the postponed Event has taken place or outstanding customer liabilities have been reasonably resolved."),
  c("pg.16_artist_performer_changes", "ARTIST / PERFORMER CHANGES", "16.1 The Promoter is responsible for all artists and performers advertised for the Event.\n16.2 Any artist cancellation, replacement, withdrawal, visa issue, travel issue, illness, contractual dispute or failure to appear shall be the responsibility of the Promoter unless otherwise expressly agreed.\n16.3 The Promoter shall promptly notify Bilit of any material change to the advertised Event.\n16.4 Bilit may require the Promoter to provide revised Event information before continuing ticket sales.\n16.5 Any customer refund obligation arising from an artist change shall be determined in accordance with applicable law, the Event terms and the circumstances of the change."),
  c("pg.17_refunds", "REFUNDS", "17.1 The Promoter authorises Bilit to process refunds on the Promoter's behalf where appropriate.\n17.2 The Promoter shall provide sufficient funds for required refunds.\n17.3 Bilit may refund customers directly from ticket revenue or other funds held.\n17.4 The Promoter shall reimburse Bilit for any refund amount not covered by available Event funds.\n17.5 Where UK consumer law applies, mandatory statutory refund rights shall take precedence over any conflicting contractual provision.\n17.6 Nothing in this Agreement shall be interpreted as removing a mandatory consumer right."),
  c("pg.18_chargebacks_payment_disputes_and_promote", "CHARGEBACKS, PAYMENT DISPUTES AND PROMOTER LIABILITY", "18.1 Responsibility for Event-related transactions. The Promoter acknowledges and agrees that, where Bilit processes ticket payments for an Event through its payment processing account, Bilit may be the merchant-facing party for payment processing purposes. Notwithstanding this payment processing arrangement, the Promoter shall remain responsible for all liabilities arising from the Promoter's Events, including valid Customer claims, refunds, cancellations, Chargebacks, payment reversals and other payment disputes attributable to an Event or the Promoter.\n18.2 General rule. The Promoter shall bear the economic responsibility for all Chargebacks, payment reversals and payment disputes relating to Tickets for its Events, whatever their stated reason (including fraud, unrecognised-transaction and non-receipt claims), except to the extent caused directly by Bilit's own breach of this Agreement.\n18.3 Chargebacks and payment disputes. Without limiting clause 18.2, where a Customer initiates a Chargeback, card dispute, payment reversal or similar claim in relation to a Ticket purchased for the Promoter's Event, the Promoter shall be responsible for the disputed Ticket amount where the underlying liability relates to the Event, the Promoter, the Ticket, the provision of the Event, cancellation, material change, failure to provide the Event, failure to provide the purchased Ticket or any other matter within the Promoter's responsibility.\n18.4 Amounts deducted from Bilit's payment account. If Stripe, a card scheme, acquiring bank, payment processor or other financial institution deducts, freezes, reverses or withholds any amount from Bilit's payment account in connection with a transaction relating to the Promoter's Event, the Promoter shall reimburse Bilit for the relevant amount. This includes, where applicable:\n• the disputed transaction amount;\n• chargeback and dispute fees;\n• payment reversal fees;\n• bank or payment processor fees;\n• reasonable third-party recovery costs; and\n• other directly incurred costs arising from the relevant payment dispute.\n18.5 Right of set-off. Bilit shall be entitled, without further consent from the Promoter, to deduct any amount owed by the Promoter under this clause from:\n• Ticket sales proceeds and Funds Held;\n• current or future settlements for any Event;\n• amounts otherwise payable to the Promoter;\n• deposits or reserves held by Bilit; or\n• any other amounts payable by Bilit to the Promoter or its Affiliates.\nThe Promoter authorises Bilit to make such deductions to recover amounts due under this Agreement. This clause is in addition to clause 10.5.\n18.6 Insufficient settlement funds. If there are insufficient funds otherwise payable to the Promoter to recover the relevant amount, Bilit may issue an invoice or written demand to the Promoter. The Promoter shall pay the outstanding amount within seven (7) calendar days of receiving such demand, failing which clause 10.7 (interest and recovery costs) applies.\n18.7 Reserve and withholding. Where Bilit reasonably considers that there is a potential Chargeback, refund or payment-dispute risk associated with an Event, Bilit may retain a reserve from the amounts otherwise payable to the Promoter for the purpose of covering potential liabilities. The amount and duration of any such reserve shall be reasonably related to the anticipated payment, refund and Chargeback exposure associated with the Event, and this clause is without prejudice to clause 60.\n18.8 Promoter's obligation to cooperate. The Promoter shall, within five (5) Business Days of request, provide Bilit with all information and documentation reasonably required to respond to a Chargeback or payment dispute, including evidence of Ticket delivery, Ticket validity, Event attendance, Customer communications, Event terms, cancellation notices and other relevant documentation. Where the Promoter fails to do so, the Promoter shall bear the full amount of the relevant Chargeback and associated costs.\n18.9 Bilit's right to contest disputes. Where appropriate, Bilit may submit evidence to Stripe, the relevant payment processor, card network or financial institution to contest a Chargeback or payment dispute. Bilit may decide, acting reasonably, whether and how to contest any Chargeback. The Promoter acknowledges that the final decision on a card Chargeback is made through the applicable card-network and issuing-bank dispute process and is not determined by Bilit or Stripe, and that an unsuccessful contest does not reduce the Promoter's liability under this clause.\n18.10 Event cancellation or material change. Where an Event is cancelled, materially changed or otherwise gives rise to a legal entitlement to a Customer refund, the Promoter shall remain responsible for the financial consequences of that cancellation, material change or other Promoter-related event, including all amounts which Bilit is required to refund to Customers.\n18.11 Continuing obligation. The Promoter's obligations under this clause shall survive the completion, cancellation or termination of the Event and the termination of this Agreement for as long as any Chargeback, refund, reversal, dispute or related liability may arise from a Ticket transaction processed during the term of this Agreement under the applicable card scheme or payment processor rules.\n18.12 No limitation of consumer rights. Nothing in this Agreement shall be interpreted as limiting, excluding or transferring any mandatory statutory rights or remedies available to consumers. This clause governs the allocation of financial responsibility between Bilit and the Promoter and does not prevent a Customer from exercising rights available under Applicable Law."),
  c("pg.19_customer_claims", "CUSTOMER CLAIMS", "19.1 The Promoter shall be responsible for claims arising from:\n• cancellation;\n• postponement;\n• venue problems;\n• performer problems;\n• event content;\n• event safety;\n• access;\n• seating;\n• event production;\n• failure to provide advertised services;\n• misrepresentation of the Event.\n19.2 Bilit may assist with customer communication but shall not become responsible for the underlying Promoter obligation."),
  c("pg.20_venue", "VENUE", "20.1 The Promoter is responsible for ensuring that the venue is properly booked and authorised for the Event.\n20.2 The Promoter shall ensure that the venue can legally accommodate the advertised audience capacity.\n20.3 Bilit shall not be liable for:\n• venue cancellation;\n• venue closure;\n• venue damage;\n• venue overbooking;\n• venue restrictions;\n• security problems;\n• venue licensing;\n• venue capacity issues."),
  c("pg.21_event_safety", "EVENT SAFETY", "21.1 The Promoter is solely responsible for the safety and security of the Event.\n21.2 The Promoter shall provide sufficient:\n• security personnel;\n• medical support where required;\n• crowd management;\n• emergency procedures;\n• fire safety;\n• evacuation procedures;\n• qualified staff.\n21.3 The Promoter shall comply with all applicable health and safety legislation."),
  c("pg.22_insurance", "INSURANCE", "The Promoter shall maintain appropriate insurance for the Event, including where appropriate:\n• public liability insurance;\n• employer's liability insurance;\n• event cancellation insurance;\n• equipment insurance;\n• professional liability insurance;\n• artist/performer insurance.\nBilit may request evidence of insurance before allowing an Event to go live."),
  c("pg.23_indemnity", "INDEMNITY", "The Promoter shall indemnify and keep indemnified Bilit, its directors, officers, employees, contractors and service providers against claims, losses, liabilities, damages, penalties, costs and reasonable legal expenses arising out of or relating to:\na. the Event;\nb. cancellation or postponement of the Event;\nc. the Promoter's breach of this Agreement;\nd. breach of applicable law;\ne. failure to obtain licences;\nf. venue disputes;\ng. artist disputes;\nh. intellectual property claims;\ni. customer claims caused by the Promoter;\nj. injury, death or property damage caused by the Event or Promoter;\nk. fraud or misconduct by the Promoter;\nl. tax liabilities;\nm. regulatory penalties attributable to the Promoter.\nThis indemnity shall not apply to the extent that a loss is finally determined to have been caused by Bilit's own breach, negligence or wilful misconduct."),
  c("pg.24_limitation_of_liability", "LIMITATION OF LIABILITY", "24.1 Nothing in this Agreement shall exclude or limit liability to the extent prohibited by applicable law.\n24.2 Subject to mandatory law, Bilit shall not be liable for indirect, consequential, special or economic losses, including loss of profit, loss of reputation, loss of business or loss of anticipated revenue.\n24.3 Subject to clause 24.1, Bilit's total aggregate liability arising out of or in connection with this Agreement and all Event Schedules, whether in contract, tort (including negligence), breach of statutory duty, misrepresentation or otherwise, shall not exceed the total Booking Fees actually received and retained by Bilit from the Promoter's Events in the 12 months immediately preceding the date on which the claim arose.\n24.4 The limitation in this clause shall not apply where applicable law prohibits such limitation.\n24.5 Bilit shall not be liable for any failure, delay or loss caused by payment processors, banks, card schemes, hosting or telecommunications providers, venues, performers or other third parties outside Bilit's control, or by any act or omission of the Promoter.\n24.6 Any claim against Bilit must be notified to Bilit in writing, with reasonable particulars, within 6 months after the Promoter became aware (or ought reasonably to have become aware) of the circumstances giving rise to it, and proceedings must be commenced within 12 months after that date; otherwise the claim is waived and barred.\n24.7 The Promoter acknowledges that it enters into this Agreement in the course of business, that it has had the opportunity to take legal advice, and that the limitations and exclusions in this clause are reasonable having regard to the fees payable to Bilit and the insurance the Promoter is required to maintain."),
  c("pg.25_force_majeure", "FORCE MAJEURE", "Neither Party shall be liable for failure or delay caused by circumstances beyond its reasonable control, including:\n• war;\n• terrorism;\n• civil unrest;\n• government action;\n• natural disaster;\n• epidemic or pandemic;\n• fire;\n• flood;\n• extreme weather;\n• venue destruction;\n• major transport disruption;\n• internet infrastructure failure;\n• payment network failure;\n• cyberattack;\n• sanctions;\n• governmental restrictions.\nHowever, Force Majeure shall not excuse or suspend any obligation to pay money, including the Promoter's obligations to fund customer refunds, repay Advance Payments, pay chargebacks and pay any other Promoter Debt."),
  c("pg.26_intellectual_property", "INTELLECTUAL PROPERTY", "26.1 The Promoter grants Bilit a non-exclusive, worldwide, royalty-free licence to use Event-related:\n• names;\n• logos;\n• photographs;\n• videos;\n• artwork;\n• promotional materials;\n• artist information;\n• trademarks;\nfor the purposes of ticketing, marketing, advertising and operating the Event.\n26.2 The Promoter warrants that it has the right to grant this licence.\n26.3 Bilit retains all rights in its software, platform, technology, database, designs, systems and intellectual property."),
  c("pg.27_marketing", "MARKETING", "27.1 Bilit may advertise the Event through its website, social media, email, advertising platforms and other marketing channels.\n27.2 The Promoter shall provide accurate promotional materials.\n27.3 Bilit may refuse promotional content that is misleading, illegal, offensive, infringing or otherwise unsuitable for the Platform."),
  c("pg.28_data_protection", "DATA PROTECTION", "28.1 Each Party shall comply with applicable data protection and privacy laws.\n28.2 Bilit may process customer information for:\n• ticket fulfilment;\n• customer support;\n• payment processing;\n• fraud prevention;\n• Event administration;\n• legal compliance;\n• reporting.\n28.3 The Parties shall enter into any additional data processing agreement reasonably required by applicable law.\n28.4 The Promoter shall not unlawfully access, copy, sell or misuse customer information obtained through the Platform."),
  c("pg.29_customer_data", "CUSTOMER DATA", "29.1 Customer data collected through Bilit's Platform shall remain subject to Bilit's privacy policy and applicable data protection law.\n29.2 The Promoter shall only use customer data where legally permitted and for legitimate Event-related purposes.\n29.3 The Promoter shall not use customer data for unrelated marketing unless it has a lawful basis and all required consents have been obtained."),
  c("pg.30_fraud_and_security", "FRAUD AND SECURITY", "Bilit may implement fraud prevention, ticket security and transaction monitoring measures.\nBilit may suspend transactions, tickets or accounts where reasonably necessary to investigate suspected fraud or security threats."),
  c("pg.31_ticket_control", "TICKET CONTROL", "31.1 Bilit may determine the technical format of tickets.\n31.2 Tickets may contain:\n• QR codes;\n• barcodes;\n• unique identifiers;\n• customer information;\n• seating information;\n• access conditions.\n31.3 The Promoter must not duplicate, manipulate or unlawfully reproduce Bilit-issued tickets.\n31.4 The Promoter shall use Bilit's approved scanning and admission systems where required."),
  c("pg.32_event_capacity", "EVENT CAPACITY", "The Promoter shall not sell or permit admission beyond the lawful capacity of the venue.\nThe Promoter shall be responsible for any consequences arising from overselling, unauthorised admissions or inaccurate capacity information supplied to Bilit."),
  c("pg.33_taxes", "TAXES", "33.1 The Promoter is responsible for its own taxes arising from the Event.\n33.2 Bilit may deduct or withhold taxes where legally required.\n33.3 The Promoter shall provide accurate tax and business information when requested.\n33.4 Each Party shall cooperate reasonably with tax authorities and payment processors where legally required."),
  c("pg.34_currency_and_international_payments", "CURRENCY AND INTERNATIONAL PAYMENTS", "34.1 The Event Schedule shall specify the settlement currency.\n34.2 Where ticket sales occur in another currency, exchange rates and conversion charges may apply.\n34.3 Bilit shall not be responsible for fluctuations in foreign exchange rates.\n34.4 International bank transfers may be subject to bank charges, intermediary bank charges and processing delays."),
  c("pg.35_sanctions_and_aml", "SANCTIONS AND AML", "The Promoter warrants that neither it nor, to its knowledge, its beneficial owners or relevant Event parties are subject to applicable sanctions that would prohibit the transaction.\nBilit may suspend or terminate services where required by applicable sanctions, anti-money-laundering or financial-crime requirements."),
  c("pg.36_audit_and_records", "AUDIT AND RECORDS", "The Promoter shall retain relevant Event records for the period required by applicable law.\nBilit may request reasonable documentation concerning:\n• ticket sales;\n• venue agreements;\n• licences;\n• insurance;\n• artist contracts;\n• ownership;\n• tax information;\n• customer claims."),
  c("pg.37_confidentiality", "CONFIDENTIALITY", "Each Party shall keep confidential commercially sensitive information received from the other Party.\nThis obligation shall not apply to information that:\n• is publicly available;\n• was already lawfully known;\n• is independently developed;\n• must be disclosed by law or competent authority."),
  c("pg.38_promoter_account", "PROMOTER ACCOUNT", "The Promoter shall maintain accurate account information.\nThe Promoter shall not:\n• share account credentials;\n• allow unauthorised access;\n• impersonate another person;\n• provide false identity information.\nThe Promoter is responsible for activity carried out through authorised account credentials, subject to applicable law."),
  c("pg.39_suspension", "SUSPENSION", "Bilit may temporarily suspend the Event or Promoter account where reasonably necessary to:\n• investigate fraud;\n• investigate a legal complaint;\n• protect customers;\n• protect funds;\n• comply with law;\n• comply with payment processor requirements;\n• prevent financial loss;\n• investigate breach of this Agreement."),
  c("pg.40_termination", "TERMINATION", "Either Party may terminate this Agreement by giving 30 days' written notice, unless otherwise stated in an Event Schedule.\nBilit may terminate immediately where:\na. the Promoter commits a material breach;\nb. the breach cannot reasonably be remedied;\nc. the Promoter becomes insolvent;\nd. fraud is suspected;\ne. continued service would expose Bilit to material legal or financial risk;\nf. payment processing is terminated;\ng. the Promoter fails to pay amounts due;\nh. the Promoter undergoes a change of control without Bilit's prior written consent;\ni. the Promoter or any of its directors or beneficial owners becomes subject to sanctions or is involved in conduct that, in Bilit's reasonable opinion, may bring Bilit into disrepute."),
  c("pg.41_effect_of_termination", "EFFECT OF TERMINATION", "Termination shall not affect rights or liabilities accrued before termination.\nClauses relating to:\n• payment;\n• refunds;\n• chargebacks;\n• indemnity;\n• confidentiality;\n• intellectual property;\n• data;\n• limitation of liability;\n• dispute resolution;\nshall survive termination to the extent necessary.\nOn termination for any reason, all Promoter Debts and unrecovered Advance Payments become immediately due, and Bilit may retain Funds Held until the end of the period during which refunds and chargebacks may reasonably arise, after which any balance shall be paid to the Promoter subject to set-off."),
  c("pg.42_no_partnership", "NO PARTNERSHIP", "Save for the limited payment collection role described in clause 11.9, nothing in this Agreement creates:\n• a partnership;\n• joint venture;\n• employment relationship;\n• agency relationship;\nbetween the Parties unless expressly agreed in writing.\nThe Promoter has no authority to bind Bilit."),
  c("pg.43_subcontracting", "SUBCONTRACTING", "Bilit may use third-party providers to perform services.\nThis may include:\n• payment processors;\n• hosting providers;\n• cloud providers;\n• email providers;\n• fraud prevention providers;\n• analytics providers;\n• customer support providers."),
  c("pg.44_assignment", "ASSIGNMENT", "The Promoter may not assign this Agreement without Bilit's prior written consent.\nBilit may assign or transfer this Agreement to an affiliated company, successor or purchaser of substantially all of its relevant business, subject to applicable law."),
  c("pg.45_notices", "NOTICES", "Notices may be provided by:\n• email;\n• Platform notification;\n• registered post;\n• electronic contract system.\nElectronic communications shall be considered written communications for the purposes of this Agreement where legally permitted."),
  c("pg.46_electronic_signature", "ELECTRONIC SIGNATURE", "The Parties agree that electronic signatures may be used to execute this Agreement.\nAn electronic signature, digital signature, checkbox acceptance, OTP verification or equivalent electronic acceptance may constitute evidence of the Promoter's agreement where legally valid.\nBilit shall retain an electronic record containing, where available:\n• signer name;\n• email;\n• IP address;\n• timestamp;\n• document version;\n• signature status;\n• audit trail;\n• acceptance record."),
  c("pg.47_entire_agreement", "ENTIRE AGREEMENT", "This Agreement, together with each Event Schedule and any expressly incorporated documents, constitutes the entire agreement between the Parties concerning the relevant Event.\nIt supersedes prior discussions concerning the same subject matter.\nEach Party acknowledges that, in entering into this Agreement, it has not relied on any statement, representation, assurance or warranty that is not expressly set out in this Agreement or an Event Schedule. Nothing in this clause limits or excludes liability for fraud.\nA person who is not a Party has no right under the Contracts (Rights of Third Parties) Act 1999 or otherwise to enforce any term of this Agreement, except the persons indemnified under clause 23."),
  c("pg.48_amendments", "AMENDMENTS", "Any material amendment must be agreed in writing.\nBilit may update standard Platform policies from time to time, provided that such update does not retrospectively alter material commercial terms already agreed for an Event unless required by law or expressly agreed."),
  c("pg.49_severability", "SEVERABILITY", "If any provision is held invalid or unenforceable, the remaining provisions shall remain in force.\nThe Parties shall seek to replace the invalid provision with a valid provision that most closely reflects the original commercial purpose."),
  c("pg.50_waiver", "WAIVER", "Failure by either Party to enforce a provision shall not constitute a waiver of that provision.\nThe rights and remedies of Bilit under this Agreement are cumulative and in addition to any rights and remedies provided by law."),
  c("pg.51_governing_law", "GOVERNING LAW", "Unless otherwise stated in the Event Schedule, this Agreement and any non-contractual obligations arising out of or in connection with it shall be governed by international commercial law, namely the UNIDROIT Principles of International Commercial Contracts (2016).\nMatters not expressly settled by the UNIDROIT Principles shall be governed by the laws of England and Wales.\nNothing in this clause deprives any person of the protection of the mandatory laws of the country where an Event takes place, including mandatory consumer protection laws (see clause 54).\nTo the fullest extent permitted by the UNIDROIT Principles, the express terms of this Agreement prevail over any principle or implied term, and Articles 6.2.1 to 6.2.3 (Hardship) of the UNIDROIT Principles shall not apply. The Parties agree that the allocation of risk in this Agreement, including under clauses 9, 12, 13, 18, 23, 24 and 25, reflects their agreed commercial bargain and shall not be adapted or reopened on grounds of changed circumstances."),
  c("pg.52_international_arbitration", "INTERNATIONAL ARBITRATION", "Any dispute arising out of or in connection with this Agreement, including any question regarding its existence, validity or termination, which is not resolved under clause 53 shall be referred to and finally resolved by international arbitration under the UNCITRAL Arbitration Rules in force at the date of the dispute.\nThe tribunal shall consist of one arbitrator. The appointing authority shall be the Secretary-General of the Permanent Court of Arbitration at The Hague. The seat of arbitration shall be Ras Al Khaimah, United Arab Emirates. The language of the arbitration shall be English.\nThe award shall be final and binding on the Parties and may be enforced in any court of competent jurisdiction, including under the New York Convention on the Recognition and Enforcement of Foreign Arbitral Awards.\nFor international Events, the Parties may expressly agree to an alternative seat or arbitral institution in the applicable Event Schedule.\nNothing in this clause prevents either Party from seeking urgent interim or protective relief from any competent court, or from bringing proceedings to recover undisputed debts."),
  c("pg.53_dispute_resolution", "DISPUTE RESOLUTION", "The Parties shall first attempt to resolve disputes through good-faith negotiations.\nA Party raising a dispute shall provide written notice describing:\n• the dispute;\n• relevant facts;\n• requested resolution.\nThe Parties shall attempt to resolve the dispute within 14 calendar days.\nNothing prevents either Party from seeking urgent injunctive or protective relief where necessary."),
  c("pg.54_compliance_with_local_law", "COMPLIANCE WITH LOCAL LAW", "The Promoter acknowledges that an Event may be subject to laws different from the laws governing this Agreement.\nThe Promoter remains responsible for complying with the mandatory laws of the country, state, province or municipality where the Event takes place."),
  c("pg.55_no_guarantee_of_sales", "NO GUARANTEE OF SALES", "Bilit does not guarantee:\n• a minimum number of tickets sold;\n• revenue;\n• attendance;\n• advertising performance;\n• payment success;\n• Event profitability."),
  c("pg.56_platform_availability", "PLATFORM AVAILABILITY", "Bilit will use commercially reasonable efforts to maintain Platform availability.\nBilit does not guarantee uninterrupted or error-free operation.\nBilit shall not be responsible for outages caused by third-party providers or circumstances beyond its reasonable control, subject to applicable law."),
  c("pg.57_promoter_s_responsibility_for_advertisin", "PROMOTER'S RESPONSIBILITY FOR ADVERTISING", "The Promoter is responsible for ensuring that all advertising is accurate.\nThe Promoter shall not advertise:\n• incorrect artists;\n• incorrect dates;\n• incorrect venue information;\n• false ticket categories;\n• misleading VIP benefits;\n• unavailable services;\n• unauthorised claims."),
  c("pg.58_vip_meet_greet_special_access", "VIP / MEET & GREET / SPECIAL ACCESS", "Where an Event includes VIP, Meet & Greet, backstage, premium seating or other special benefits, the Promoter shall ensure that such benefits are actually delivered.\nFailure to deliver such benefits may result in customer claims and refunds for which the Promoter shall be financially responsible, subject to applicable law."),
  c("pg.59_promoter_default", "PROMOTER DEFAULT", "A Promoter shall be considered in default if it:\n• fails to pay amounts due;\n• fails to refund required amounts;\n• cancels without adequate arrangements;\n• materially misrepresents an Event;\n• fails to provide required licences;\n• causes material customer claims;\n• breaches this Agreement;\n• becomes insolvent or subject to any insolvency, winding-up, administration or similar proceeding in any jurisdiction;\n• undergoes a change of control without notifying Bilit;\n• provides false or misleading information to Bilit.\nUpon default, Bilit may:\n• suspend ticket sales;\n• retain settlement funds;\n• offset amounts;\n• require additional security;\n• demand immediate payment;\n• terminate the Event;\n• terminate the Agreement;\n• pursue legal remedies."),
  c("pg.60_security_reserve", "SECURITY / RESERVE", "Where Bilit reasonably considers an Event high-risk, Bilit may require:\n• a deposit;\n• reserve;\n• security payment;\n• personal/corporate guarantee;\n• evidence of insurance;\n• additional documentation.\nThe amount and release conditions may be specified in the Event Schedule.\nWithout limiting the above, Bilit may withhold all or part of the Funds Held for an Event as a reserve until 90 days after the Event, and for longer where refunds, chargebacks, customer claims or disputes remain outstanding. Any reserve may be applied against Promoter Debts."),
  c("pg.61_no_personal_liability_of_promoter_repres", "NO PERSONAL LIABILITY OF PROMOTER REPRESENTATIVE", "Where the Promoter is a limited company, the individual signing on its behalf signs as an authorised representative and does not personally assume liability unless a separate personal guarantee is expressly executed."),
  c("pg.62_personal_guarantee_optional", "PERSONAL GUARANTEE \u2014 OPTIONAL", "Where required by Bilit, the Promoter's director/shareholder may execute a separate Personal Guarantee.\nThe Personal Guarantee shall be a separate document and shall identify the specific obligations guaranteed."),
  c("pg.63_counterparts", "COUNTERPARTS", "This Agreement may be executed electronically and in counterparts.\nEach electronically executed counterpart shall constitute an original to the extent permitted by applicable law."),
  c("pg.64_language", "LANGUAGE", "This Agreement may be translated for convenience.\nUnless otherwise agreed, the English version shall prevail in the event of inconsistency between language versions, subject to mandatory applicable law."),
  c("pg.65_order_of_precedence", "ORDER OF PRECEDENCE", "In case of inconsistency:\n1. mandatory applicable law;\n2. signed Event Schedule;\n3. this Agreement;\n4. Platform policies;\n5. other documentation."),
];
